package com.bank.dsa;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.*;

// Runnable demo: reconcile 10 shift deposits into one total.
public class SumOfTenDemo {
    private static final Logger log = Logger.getLogger(SumOfTenDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TillReconciler reconciler = new TillReconciler();

        List<BigDecimal> deposits = new ArrayList<>();
        for (int k = 1; k <= 10; k++) {                 // deposits: 1000..10000
            deposits.add(new BigDecimal(k + "000.00"));
        }
        BigDecimal total = reconciler.sum(deposits);
        log.info(() -> "Shift till total over 10 deposits = Rs." + total);
    }
}

// ─── Would be in TillReconciler.java in a real project ───
class TillReconciler {
    // sum = 0 (additive identity); for each deposit { sum = sum + x }.
    BigDecimal sum(List<BigDecimal> deposits) {
        if (deposits == null) {
            throw new IllegalArgumentException("Deposits must not be null");
        }
        BigDecimal sum = BigDecimal.ZERO;               // seed = additive identity (NOT 1)
        for (BigDecimal x : deposits) {                 // loop while more to read
            if (x == null) {
                throw new IllegalArgumentException("Deposit amount must not be null");
            }
            sum = sum.add(x);                           // sum = sum + x (exact)
        }
        return sum.setScale(2, java.math.RoundingMode.HALF_EVEN);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
